  return {
    count: 0,
    min: null,
    max: null,
    mean: null,
    median: null,
    p95: null,
    stddev: null,
  };
}

// shell 下 127=命令未找到、126=命令不可执行，均属"进程无法启动"。
function isStartupExitCode(code) {
  return code === 126 || code === 127;
