  if (fatalSpawn) {
    return EXIT_USAGE;
  }

  const summary = samples.length === 0
    ? emptySummary()
    : computeSummary(samples.map((s) => s.duration_ns));

  const report = {
    command,
    runs,
    warmup,
    timeout_ms: timeoutMs,
    unit: 'ns',
    samples,
    summary,
    errors,
  };

  let payload;
  try {
    payload = JSON.stringify(report, null, 2) + '\n';
  } catch (err) {
    process.stderr.write(`perf-regress: 结果序列化失败: ${err.message}\n`);
